/** Génère un CSV au format de l'export Airtable de la table BDD (57 colonnes), avec des données FICTIVES. */
export const AIRTABLE_HEADERS = [
  "Prénom",
  "Nom",
  "Email",
  "Poste",
  "Linkedin",
  "Entreprise",
  "Site web",
  "Secteur",
  "Taille",
  "Linkedin Entreprise",
  "Année de création",
  "Adresse complète Entreprise",
  "Etat",
  "Ville",
  "Pays",
  "Téléphone",
  "Description entreprise",
  "Qualification",
  "Service recommandé",
  "Raison",
  "Email objet",
  "Email corps",
  "Date détection",
  "Persona",
  "Source",
  "Validation mail",
  "Email envoyé le",
  "Statut email",
  "Étape pipeline",
  "Valeur deal",
  "Pack",
  "Statut appel",
  "Prochaine action Ifaliana",
  "Responsable",
  "Trafic organique",
  "Autorité domaine",
  "Mots-clés organiques",
  "Backlinks",
  "CMS",
  "E-commerce",
  "Tracking GTM",
  "Tracking GA4",
  "Pixel Meta",
  "Signal Google Ads",
  "SSL",
  "Categorie Google Maps",
  "Note Google",
  "Coordonnees GPS",
  "Nombre avis Google",
  "Version_prompt_email",
  "Derniere validation",
  "Prochaine action Kate",
  "Fiche Google My Business",
  "RELANCE 1",
  "STATUT",
  "RELANCE 2",
  "COMMENTAIRE",
] as const;

export type AirtableRow = Partial<Record<(typeof AIRTABLE_HEADERS)[number], string>>;

const quote = (v: string) => (/[",\n\r]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

export function toCsv(rows: AirtableRow[]): string {
  const lines = [AIRTABLE_HEADERS.join(",")];
  for (const r of rows) lines.push(AIRTABLE_HEADERS.map((h) => quote(r[h] ?? "")).join(","));
  return `﻿${lines.join("\n")}\n`;
}

